package packet;
import core.*;
public final class UdpDatagram{private final int sourcePort;private final int destinationPort;private final int length;private final byte[] payload;public UdpDatagram(int sourcePort,int destinationPort,int length,byte[] payload){this.sourcePort=sourcePort;this.destinationPort=destinationPort;this.length=length;this.payload=payload==null?new byte[0]:payload;}public static ParseResult<UdpDatagram> parse(byte[] data){Diagnostics d=new Diagnostics();if(data==null||data.length<8)return ParseResult.failure("udp.truncated","UDP header truncated");int sp=Endian.u16be(data,0);int dp=Endian.u16be(data,2);int len=Endian.u16be(data,4);if(len<8)d.high("udp.length","UDP length shorter than header");if(len>data.length){d.medium("udp.truncated","UDP length exceeds captured data");len=data.length;}return ParseResult.of(new UdpDatagram(sp,dp,len,SafeSlice.copy(data,8,Math.max(0,len-8))),d);}public int sourcePort(){return sourcePort;}public int destinationPort(){return destinationPort;}public int length(){return length;}public byte[] payload(){return payload;}}
